#include <vector>
#include <algorithm>
#include <climits>

using namespace std;

class Solution {
public:
    int findTheCity(int n, vector<vector<int>>& edges, int distanceThreshold) {
        vector<vector<int>> dist(n, vector<int>(n, INT_MAX / 2));
        for (int i = 0; i < n; ++i) dist[i][i] = 0;

        for (auto& e : edges) {
            dist[e[0]][e[1]] = e[2];
            dist[e[1]][e[0]] = e[2];
        }

        for (int k = 0; k < n; ++k)
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j)
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);

        int res = -1, minReach = n;
        for (int i = 0; i < n; ++i) {
            int reach = 0;
            for (int j = 0; j < n; ++j) {
                if (i != j && dist[i][j] <= distanceThreshold)
                    reach++;
            }
            if (reach <= minReach) {
                minReach = reach;
                res = i;
            }
        }
        return res;
    }
};
